questions.model:
原子直接输出字母；表先输出(，按序处理各元素，除第一项外先输出逗号，再递归输出元素，最后输出)。空表直接()。用输出流或可增长缓冲避免每层重复联接造成额外复制；时间O(输出长度)，递归栈O(D)。

参考实现：
```c
static int emitG(const GNode*p,char out[],int at){if(p->tag==GL_ATOM){out[at++]=(char)p->atom;return at;}out[at++]='(';for(int i=0;i<p->length;i++){if(i)out[at++]=',';at=emitG(p->items[i],out,at);}out[at++]=')';return at;}
int formatGList(const GNode*root,char out[]){int n=emitG(root,out,0);out[n]=0;return n;}
```

遍历每层元素，原子追加输出尾部，子表递归展开；不输出括号或空表。重复值按出现次数保留。若有共享子表，按引用位置展开。无共享树结构O(N)时间，输出A个原子，栈O(D)；共享结构成本应按展开访问次数计算。

参考实现：
```c
static int appendAtoms(const GNode*p,int out[],int at){if(p->tag==GL_ATOM){out[at++]=p->atom;return at;}for(int i=0;i<p->length;i++)at=appendAtoms(p->items[i],out,at);return at;}
int flattenAtoms(const GNode*root,int out[]){return appendAtoms(root,out,0);}
```

维护输入位置递归parse：读字母得原子；读左括号后若下一项为右括号得空表，否则解析一个G，再循环逗号后解析G，最后要求右括号。顶层成功后跳空格并检查输入结束。缺项、尾逗号、缺右括号、非法字符均失败。每字节有限访问O(n)，栈O(D)，深度需防资源耗尽。

参考实现：
```c
static void skipSpaces(const unsigned char*s,int n,int*p){while(*p<n&&s[*p]==32)(*p)++;}
static int parseG(const unsigned char*s,int n,int*p){skipSpaces(s,n,p);if(*p>=n)return 0;unsigned char c=s[*p];if((c>='A'&&c<='Z')||(c>='a'&&c<='z')){(*p)++;return 1;}if(c!='(')return 0;(*p)++;skipSpaces(s,n,p);if(*p<n&&s[*p]==')'){(*p)++;return 1;}if(!parseG(s,n,p))return 0;while(1){skipSpaces(s,n,p);if(*p>=n)return 0;if(s[*p]==')'){(*p)++;return 1;}if(s[*p]!=',')return 0;(*p)++;if(!parseG(s,n,p))return 0;}}
int isGListText(const unsigned char s[],int n){int p=0;if(!parseG(s,n,&p))return 0;skipSpaces(s,n,&p);return p==n;}
```

函数visit(L,level)遍历该表各元素；原子则count[level]++，子表则visit(child,level+1)。初始visit(root,1)。空表无元素自然贡献0。O(N)访问时间，计数空间O(D)，递归栈O(D)（逐层循环版本）；计数类型须足够。

参考实现：
```c
static void tallyLevel(const GNode*p,int level,long long out[]){if(p->tag==GL_ATOM){out[level-1]++;return;}for(int i=0;i<p->length;i++)tallyLevel(p->items[i],level+1,out);}
void countAtomsByLevel(const GNode*root,long long counts[],int levels){for(int i=0;i<levels;i++)counts[i]=0;tallyLevel(root,0,counts);}
```
